import json
from pathlib import Path
def read_json(path):
    try:
        with Path(path).open('r', encoding='utf-8') as f: return {'ok': True, 'data': json.load(f)}
    except FileNotFoundError: return {'ok': False, 'error': 'file_not_found'}
    except json.JSONDecodeError as e: return {'ok': False, 'error': f'invalid_json: {e.msg}'}
